CREATE FUNCTION rentmate_lease_overlap_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.status IN ('EXPIRED','TERMINATED') OR NEW.deleted_at IS NOT NULL THEN RETURN NEW; END IF;
 PERFORM 1 FROM units WHERE organization_id=NEW.organization_id AND id=NEW.unit_id AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23503',MESSAGE='Lease unit is unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM leases l WHERE l.organization_id=NEW.organization_id AND l.unit_id=NEW.unit_id AND l.id<>NEW.id AND l.deleted_at IS NULL AND l.status NOT IN ('EXPIRED','TERMINATED') AND daterange(l.start_date,l.end_date,'[)') && daterange(NEW.start_date,NEW.end_date,'[)') AND (NEW.bed_id IS NULL OR l.bed_id IS NULL OR l.bed_id=NEW.bed_id)) THEN
 RAISE EXCEPTION USING ERRCODE='23P01',MESSAGE='Lease interval overlaps'; END IF;
 RETURN NEW;
END $$
